<template><q-page class="page"><section class="top"><div><p class="eyebrow">ADMINISTRAÇÃO</p><h1>Importar questões</h1><p>Valide o conteúdo antes de criar qualquer questão.</p></div></section><q-card flat class="card"><q-card-section class="q-gutter-md"><q-select v-model="format" outlined label="Formato" :options="['JSON','CSV']"/><q-input v-model="content" outlined type="textarea" autogrow label="Conteúdo da importação"/><q-btn unelevated no-caps color="primary" label="Validar importação" :loading="loading" @click="preview"/></q-card-section></q-card><q-banner v-if="error" rounded class="error">{{ error }}</q-banner><q-card v-if="report" flat class="card report"><q-card-section><h2>Relatório de validação</h2><p>{{ report.validRows }} linhas válidas · {{ report.invalidRows }} inválidas</p><q-list bordered separator><q-item v-for="row in report.rows" :key="row.rowNumber"><q-item-section><q-item-label>Linha {{ row.rowNumber }} — {{ row.valid ? 'válida' : 'inválida' }}</q-item-label><q-item-label v-if="row.errors.length" caption>{{ row.errors.map(item => item.message).join(' · ') }}</q-item-label></q-item-section></q-item></q-list><div v-if="report.importId" class="commit"><q-input v-model="syllabusId" outlined label="ID do edital para os rascunhos"/><q-btn unelevated no-caps color="primary" label="Confirmar linhas válidas" :loading="loading" @click="commit"/></div><q-banner v-if="success" rounded class="success">{{ success }}</q-banner></q-card-section></q-card></q-page></template>
<script setup lang="ts">import { ref } from 'vue'; import type { ImportReport } from '../../../Domain/Import/ImportRepository'; import { importUseCases } from '../../../Infrastructure/Container'; const format=ref<'JSON'|'CSV'>('JSON');const content=ref('');const syllabusId=ref('');const report=ref<ImportReport|null>(null);const error=ref('');const success=ref('');const loading=ref(false);async function preview(){loading.value=true;error.value='';success.value='';try{report.value=await importUseCases.preview(format.value,content.value)}catch(reason){error.value=reason instanceof Error?reason.message:'Não foi possível validar a importação.'}finally{loading.value=false}}async function commit(){if(!report.value?.importId)return;loading.value=true;error.value='';try{const result=await importUseCases.commit(report.value.importId,syllabusId.value);success.value=String(result.createdQuestions)+' questões criadas como rascunho.'}catch(reason){error.value=reason instanceof Error?reason.message:'Não foi possível confirmar.'}finally{loading.value=false}}</script>
<style scoped>.page{max-width:900px;margin:auto;padding:42px 34px}.eyebrow{margin:0 0 7px;color:#7187ad;font-size:11px;font-weight:800;letter-spacing:.1em}.top h1{margin:0;color:#142950;font-size:32px}.top p:not(.eyebrow),.report p{color:#71819e}.top{margin-bottom:24px}.card{border:1px solid #e5ecf6;border-radius:17px;background:#fff;box-shadow:0 8px 26px rgba(33,58,105,.04)}.report{margin-top:18px}.report h2{margin:0;color:#19315b;font-size:20px}.commit{display:flex;gap:10px;margin-top:18px}.commit .q-field{flex:1}.error{margin-top:15px;background:#fff3f2;color:#ae2f25}.success{margin-top:14px;background:#e9f8ef;color:#157343}@media(max-width:600px){.page{padding:28px 16px}.commit{flex-direction:column}}</style>
